create or replace function public.is_admin() returns boolean language sql stable security definer set search_path = '' as $$ select exists (select 1 from public.profiles where id = auth.uid() and role in ('admin','super_admin')); $$;
create or replace function public.is_super_admin() returns boolean language sql stable security definer set search_path = '' as $$ select exists (select 1 from public.profiles where id = auth.uid() and role = 'super_admin'); $$;
revoke all on function public.is_super_admin() from public, anon;
grant execute on function public.is_super_admin() to authenticated, service_role;
create table if not exists public.admin_access_requests (id uuid primary key default gen_random_uuid(), user_id uuid not null unique references public.profiles(id) on delete cascade, status text not null default 'pending' check(status in ('pending','approved','rejected')), created_at timestamptz not null default now(), reviewed_at timestamptz, reviewed_by uuid references public.profiles(id) on delete set null);
alter table public.admin_access_requests enable row level security;
revoke all on public.admin_access_requests from anon, authenticated;
grant select on public.admin_access_requests to authenticated;
create policy admin_access_requests_super_read on public.admin_access_requests for select to authenticated using ((select public.is_super_admin()));
create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path = '' as $$ declare n text; begin n:=coalesce(new.raw_user_meta_data->>'display_name',''); insert into public.profiles(id,role,display_name) values(new.id,'teacher',case when char_length(btrim(n)) between 1 and 60 then btrim(n) else left(coalesce(nullif(split_part(coalesce(new.email,''),'@',1),''),'New User'),60) end) on conflict(id) do nothing; insert into public.admin_access_requests(user_id) values(new.id) on conflict(user_id) do nothing; return new; end; $$;
create or replace function public.review_admin_access_request(p_request_id uuid,p_approve boolean) returns void language plpgsql security definer set search_path='' as $$ declare r public.admin_access_requests; begin if not(select public.is_super_admin()) then raise exception 'Only the site owner can approve accounts.' using errcode='42501'; end if; select * into r from public.admin_access_requests where id=p_request_id for update; if not found or r.status <> 'pending' then raise exception 'This request is no longer pending.' using errcode='22023'; end if; update public.admin_access_requests set status=case when p_approve then 'approved' else 'rejected' end,reviewed_at=now(),reviewed_by=auth.uid() where id=r.id; if p_approve then update public.profiles set role='admin' where id=r.user_id; end if; end; $$;
revoke all on function public.review_admin_access_request(uuid,boolean) from public,anon;
grant execute on function public.review_admin_access_request(uuid,boolean) to authenticated;